const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const chro = @import("nt-brow-chro.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
fn hasz(rig3: *rigz.Rigg, path: []const u8, nee2: []const u8) !bool { const recz = (try rig3.reco(path)) orelse return false; return std.mem.indexOf(u8, recz.body, nee2) != null; }
test "JS-built DOM is rendered locally: vendor never called, $0, vend brow" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); const out2 = try rig3.gozz("/dom"); try std.testing.expectEqualStrings("new", out2.stat); try std.testing.expectEqualStrings("brow", out2.vend); try std.testing.expectEqual(@as(i64, 1), out2.tier); try std.testing.expectEqual(@as(u64, 0), out2.micr); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.cal3.items.len); try std.testing.expect(try hasz(&rig3, "/dom", "Rendered by javascript marker alpha")); }
test "open shadow root text is extracted" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); const out2 = try rig3.gozz("/shado"); try std.testing.expectEqualStrings("brow", out2.vend); try std.testing.expect(try hasz(&rig3, "/shado", "Open shadow words visible here")); }
test "closed shadow root text is extracted through DOMSnapshot" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); const out2 = try rig3.gozz("/shadc"); try std.testing.expectEqualStrings("brow", out2.vend); try std.testing.expect(try hasz(&rig3, "/shadc", "Closed shadow words hidden inside")); }
test "brow_enab=false: no session, shell goes to the vendor render" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); rig3.ladz.sess = null; const out2 = try rig3.gozz("/dom"); try std.testing.expect(out2.tier >= 3); try std.testing.expect(!std.mem.eql(u8, out2.vend, "brow")); try std.testing.expectEqual(@as(usize, 1), rig3.vmkz.cal3.items.len); }
test "no Chrome found: ladder continues to the vendor" { var conf: cfgz.Conf = .{}; conf.brow_path_exec = "/no/such/chrome"; var rig3: rigz.Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); try std.testing.expect(!rig3.rndz.avai()); const out2 = try rig3.gozz("/dom"); try std.testing.expect(out2.tier >= 3); try std.testing.expectEqual(@as(usize, 1), rig3.vmkz.cal3.items.len); }
test "a blocked page never goes to the local browser" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); const out2 = try rig3.gozz("/blockp"); try std.testing.expect(!std.mem.eql(u8, out2.vend, "brow")); try std.testing.expectEqual(@as(u32, 0), rig3.rndz.rnds); }
test "timeout kills the browser: no process left, port closed" { var conf: cfgz.Conf = .{}; conf.brow_time_seco = 30; var rig3: rigz.Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); try rig3.skipNozz(); _ = try rig3.gozz("/dom"); rig3.rndz.conf.brow_time_seco = 1; const port = rig3.rndz.brow.?.port; var buf4: [64]u8 = undefined; const hang = rig3.srv2.urlzOfzz(&buf4, "/hang"); try std.testing.expectError(error.Timeout, rig3.rndz.ren2(rig3.aren.allocator(), hang, 0, "", .{})); try std.testing.expect(rig3.rndz.brow == null); var tri2: u32 = 0; while (!chro.portDead(allo, std.testing.io, port) and tri2 < 40) : (tri2 += 1) std.Io.sleep(std.testing.io, .fromMilliseconds(100), .awake) catch {}; try std.testing.expect(chro.portDead(allo, std.testing.io, port)); }
